function soupItems(query,maxTime){const q=query;const rows=state.recipes.filter(r=>r.category==='noodle'&&r.time<=maxTime&&(!q||searchHit(r.name,q)||r.ingredients.some(i=>searchHit(INGREDIENTS[i.id][0],q))));return rows.map(r=>`<article class="soup-option"><div class="soup-art">${foodArt(r)}</div><div><h3>${esc(r.name)}</h3><span class="pill ${r.time<=20?'':'orange'}">◷ ${r.time} phút</span><small> · ${recipePriceText(r)} / 4 người</small><p>${(r.tags||[]).slice(1).map(esc).join(' · ')||esc(r.prep)}</p></div><button class="btn small ${allowedRecipe(r,state)?'soft':''}" data-action="weekend-apply" data-id="${r.id}" ${!allowedRecipe(r,state)?'disabled':''}>${allowedRecipe(r,state)?'Chọn món ăn':'Cần tránh'}</button></article>`).join('')||'<div class="empty">Chưa có món ăn phù hợp. Thử đổi từ khóa hoặc thời gian.</div>'}
